    current_rest = 0
    has_work = False

    # Iterate over the schedule
    for i in range(n):
        if schedule[i] == 1:
            current_rest += 1
        else:
            current_rest = 0
            has_work = True
        max_rest = max(max_rest, current_rest)

    # If there's no work in the schedule, return 0
    if not has_work:
        return 0

    # Check for the possibility of wrapping around the end to the start
    if schedule[0] == 1 and schedule[-1] == 1:
        wrap_rest = 0
        for i in range(n):
            if schedule[i] == 1:
                wrap_rest += 1
            else:
                break
        for i in range(n-1, -1, -1):
            if schedule[i] == 1:
                wrap_rest += 1
            else:
                break
        max_rest = max(max_rest, wrap_rest)

    return max_rest

